CREATE TABLE public.staff_accounts (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT '', role text NOT NULL DEFAULT 'teacher' CHECK (role IN ('admin','assistant','teacher')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_accounts TO authenticated;
GRANT ALL ON public.staff_accounts TO service_role;
ALTER TABLE public.staff_accounts ENABLE ROW LEVEL SECURITY;
INSERT INTO public.staff_accounts(user_id,display_name,role) SELECT user_id,'إدارة المدرسة','admin' FROM public.user_roles WHERE role='admin' ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.school_permission(permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.staff_accounts WHERE user_id=auth.uid() AND active AND (role='admin' OR (role='assistant' AND permission IN ('students','content','schedule')) OR (role='teacher' AND permission='schedule'))) $$;
GRANT EXECUTE ON FUNCTION public.school_permission(text) TO authenticated;
CREATE POLICY "Staff reads self or administration" ON public.staff_accounts FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.school_permission('users'));
CREATE OR REPLACE FUNCTION public.assign_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.restrict_school_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF COALESCE((NEW.raw_app_meta_data->>'school_admin_created')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'School accounts must be created by administration'; END IF; RETURN NEW; END $$;
CREATE TRIGGER school_admin_created_accounts BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.restrict_school_signup();
ALTER TABLE public.registrations ADD COLUMN first_name text NOT NULL DEFAULT '', ADD COLUMN last_name text NOT NULL DEFAULT '', ADD COLUMN birth_date date, ADD COLUMN age integer, ADD COLUMN source text NOT NULL DEFAULT 'website', ADD COLUMN group_name text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.validate_school_registration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.age IS NOT NULL AND (NEW.age<0 OR NEW.age>100) THEN RAISE EXCEPTION 'Invalid age'; END IF; IF NEW.birth_date IS NOT NULL AND NEW.birth_date>current_date THEN RAISE EXCEPTION 'Invalid birth date'; END IF; IF NEW.status NOT IN ('new','contacted','confirmed','active','waiting','cancelled') THEN RAISE EXCEPTION 'Invalid registration status'; END IF; IF NEW.source NOT IN ('website','manual') THEN RAISE EXCEPTION 'Invalid registration source'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_school_registration BEFORE INSERT OR UPDATE ON public.registrations FOR EACH ROW EXECUTE FUNCTION public.validate_school_registration();
DROP POLICY "Admins read registrations" ON public.registrations;
DROP POLICY "Admins update registrations" ON public.registrations;
DROP POLICY "Admins delete registrations" ON public.registrations;
DROP POLICY "Anyone submits registration" ON public.registrations;
CREATE POLICY "Staff reads registrations" ON public.registrations FOR SELECT TO authenticated USING (public.school_permission('students'));
CREATE POLICY "Staff updates registrations" ON public.registrations FOR UPDATE TO authenticated USING (public.school_permission('students')) WITH CHECK (public.school_permission('students'));
CREATE POLICY "Administration deletes registrations" ON public.registrations FOR DELETE TO authenticated USING (public.school_permission('users'));
CREATE POLICY "Website or staff registration" ON public.registrations FOR INSERT TO anon,authenticated WITH CHECK ((status='new' AND admin_notes IS NULL AND source='website' AND group_name='') OR public.school_permission('students'));
CREATE TABLE public.school_documents (key text PRIMARY KEY, content jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.school_documents TO anon,authenticated;
GRANT INSERT,UPDATE,DELETE ON public.school_documents TO authenticated;
GRANT ALL ON public.school_documents TO service_role;
ALTER TABLE public.school_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads school content" ON public.school_documents FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Staff inserts school content" ON public.school_documents FOR INSERT TO authenticated WITH CHECK (public.school_permission(CASE WHEN key='theme' THEN 'users' ELSE 'content' END));
CREATE POLICY "Staff updates school content" ON public.school_documents FOR UPDATE TO authenticated USING (public.school_permission(CASE WHEN key='theme' THEN 'users' ELSE 'content' END)) WITH CHECK (public.school_permission(CASE WHEN key='theme' THEN 'users' ELSE 'content' END));
CREATE POLICY "Staff restores school content" ON public.school_documents FOR DELETE TO authenticated USING (public.school_permission(CASE WHEN key='theme' THEN 'users' ELSE 'content' END));
CREATE POLICY "Staff manages announcements" ON public.announcements FOR ALL TO authenticated USING (public.school_permission('content')) WITH CHECK (public.school_permission('content'));
CREATE POLICY "Staff manages photos" ON public.gallery_photos FOR ALL TO authenticated USING (public.school_permission('content')) WITH CHECK (public.school_permission('content'));
CREATE POLICY "Staff manages schedule" ON public.schedule_slots FOR ALL TO authenticated USING (public.school_permission('schedule')) WITH CHECK (public.school_permission('schedule'));
CREATE POLICY "Staff uploads school photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='gallery' AND public.school_permission('content'));
CREATE POLICY "Staff removes school photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='gallery' AND public.school_permission('content'));